/**
 * One materialized timeline row.
 */
typedef struct MarmotTimelineMessageRecord {
  char *message_id_hex;
  bool has_reports;
  struct MarmotPollProjection *poll;
  /**
   * Delivery marker for own (`direction == "sent"`) messages: NULL
   * while committed-but-undelivered (render as pending/failed),
   * the published source event id once delivered. Always set for
   * received messages.
   */
  char *source_message_id_hex;
  /**
   * Authenticated MLS source epoch behind this message's pinned
   * retention and encrypted-media decisions.
   */
  bool has_source_epoch;
  /**
   *Only meaningful when the matching `has_` flag is set.
   */
  uint64_t source_epoch;
  /**
   * Unset means no recoverable source-epoch decision; `0` means
   * retention explicitly disabled for this message.
   */
  bool has_retention_seconds;
  /**
   *Only meaningful when the matching `has_` flag is set.
   */
  uint64_t retention_seconds;
  /**
   * Exact pinned expiration timestamp, when finite.
   */
  bool has_retention_expires_at;
  /**
   *Only meaningful when the matching `has_` flag is set.
   */
  uint64_t retention_expires_at;
  char *direction;
  char *group_id_hex;
  char *sender;
  char *plaintext;
  struct MarmotMarkdownDocument content_tokens;
  uint64_t kind;
  struct MarmotMessageTag *tags;
  uintptr_t tags_len;
  /**
   * Authenticated inner app-event time, or observation time for
   * synthesized rows.
   */
  uint64_t timeline_at;
  /**
   * Local wall-clock time when this device observed the row.
   */
  uint64_t received_at;
  char *reply_to_message_id_hex;
  struct MarmotTimelineReplyPreview *reply_preview;
  char *media_json;
  /**
   * Ordered per-attachment outcomes for this message; empty when
   * it has no media. A malformed or unsupported `imeta` attachment
   * is a `Rejected` entry at its position with a typed reason; the
   * text and valid sibling attachments are unaffected.
   */
  struct MarmotMediaAttachmentOutcome *media;
  uintptr_t media_len;
  char *agent_text_stream_json;
  /**
   * Parsed view of kind-1210 group system rows. NULL for chat,
   * reactions, stream rows, and malformed assertions.
   */
  struct MarmotGroupSystemEvent *group_system;
  struct MarmotTimelineReactionSummary reactions;
  struct MarmotTimelineEditSummary *edit;
  bool deleted;
  enum MarmotDeletionSource deletion_source;
  char *deleted_by_message_id_hex;
  /**
   * Convergence invalidation reason (e.g. `LosingBranch`); NULL
   * for delivered messages.
   */
  char *invalidation_status;
  char *client_token;
} MarmotTimelineMessageRecord;

