MarmotStatus marmot_client_new_with_secret_store(const char *root_path,
                                                 const char *const *relay_urls,
                                                 uintptr_t relay_urls_len,
                                                 const struct MarmotSecretStore *store,
                                                 struct MarmotClient **out_client);

